@property
def values(self):
    """Return a dask.array of the values of this dataframe

    Warning: This creates a dask.array without precise shape information.
    Operations that depend on shape information, like slicing or reshaping,
    will not work.
    """
    if is_extension_array_dtype(self._meta.values):
        warnings.warn(
            "Dask currently has limited support for converting pandas extension dtypes "
            f"to arrays. Converting {self._meta.values.dtype} to object dtype.",
            UserWarning,
        )
        # For extension array dtypes, we need to ensure we get the same behavior as pandas
        # First, convert to pandas object to get the values with proper dtype conversion
        return self.map_partitions(lambda df: df.astype(object).values)
    return self.map_partitions(methods.values)

